// Read-only viewer for G-code generated by the production Ruby writer.
var n2gGcodePreview = (typeof n2gGcodePreview!=='undefined') ? n2gGcodePreview : {
  requestId:'',signature:'',files:{},current:null,lineMap:[],activeLine:-1,states:[]
};

function n2gGcodePreviewStatus(text,isError){
  var el=document.getElementById('tp-gcode-status');
  if(!el)return;
  el.textContent=text||'';
  el.style.display=text?'block':'none';
  el.style.color=isError?'#ff8e8e':'#9ca5b2';
}

function n2gGcodePreviewEnsure(){
  if(typeof detailMode!=='undefined'&&detailMode!=='toolpath')return;
  if(typeof n2gBuildExportPayload!=='function'||typeof n2gBuildPocketPathsForExport!=='function'){
    n2gGcodePreviewStatus('Chưa thể tạo G-code xem trước.',true);return;
  }
  try{
    if(typeof flushAll==='function')flushAll();
    var pockets=n2gBuildPocketPathsForExport();
    var profiles=n2gBuildProfilePathsForExport();
    var payload=n2gBuildExportPayload(pockets,profiles);
    payload.preview_only=true;
    payload.preview_sheet=(typeof tpZm!=='undefined'&&tpZm.sheet)?String(tpZm.sheet.name):'';
    var signature=JSON.stringify(payload);
    if(signature===n2gGcodePreview.signature&&Object.keys(n2gGcodePreview.files).length){
      n2gGcodePreviewShowCurrentSheet();return;
    }
    var id=String(Date.now())+'_'+Math.random().toString(36).slice(2);
    payload.preview_request_id=id;
    n2gGcodePreview.requestId=id;
    n2gGcodePreview.signature=signature;
    n2gGcodePreview.files={};n2gGcodePreview.current=null;n2gGcodePreview.lineMap=[];
    n2gGcodePreviewStatus('Ruby đang tạo G-code tạm…');
    var box=document.getElementById('tp-gcode-lines');if(box)box.innerHTML='';
    sketchup.export_gcode_callback(JSON.stringify(payload));
  }catch(e){n2gGcodePreviewStatus('Không tạo được G-code tạm: '+e.message,true);}
}

function n2gGcodePreviewInvalidate(){
  n2gGcodePreview.signature='';n2gGcodePreview.files={};n2gGcodePreview.current=null;
  n2gGcodePreview.lineMap=[];n2gGcodePreview.activeLine=-1;
  n2gGcodePreviewStatus('Dữ liệu đã thay đổi — mở lại Xem đường dao để tạo G-code mới.');
}

function n2gGcodePreviewReceive(requestId,files){
  if(String(requestId)!==String(n2gGcodePreview.requestId))return;
  n2gGcodePreview.files={};
  (files||[]).forEach(function(f){
    n2gGcodePreview.files[String(f.sheet)]={sheet:String(f.sheet),file:String(f.file||''),
      text:String(f.text||''),lines:String(f.text||'').replace(/\r/g,'').split('\n')};
  });
  n2gGcodePreviewStatus('');
  n2gGcodePreviewShowCurrentSheet();
  if(typeof simAnim!=='undefined'&&simAnim.segs&&simAnim.segs.length)n2gGcodePreviewBindSegments(simAnim.segs);
}

function n2gGcodePreviewError(requestId,message){
  if(String(requestId)!==String(n2gGcodePreview.requestId))return;
  if(String(message)==='busy'){
    n2gGcodePreview.signature='';
    n2gGcodePreviewStatus('Đang chờ tiến trình Ruby hiện tại…');
    setTimeout(n2gGcodePreviewEnsure,1000);
    return;
  }
  n2gGcodePreviewStatus('Lỗi tạo G-code tạm: '+String(message||''),true);
}

function n2gGcodePreviewShowCurrentSheet(){
  var name=(typeof tpZm!=='undefined'&&tpZm.sheet)?String(tpZm.sheet.name):'';
  n2gGcodePreview.current=n2gGcodePreview.files[name]||null;
  var file=document.getElementById('tp-gcode-file');if(file)file.textContent=n2gGcodePreview.current?n2gGcodePreview.current.file:'';
  n2gGcodePreview.activeLine=-1;n2gGcodePreview.lineMap=[];
  if(!n2gGcodePreview.current){
    var emptyPos=document.getElementById('tp-gcode-position');
    if(emptyPos)emptyPos.textContent='Dòng — / —';
    n2gGcodePreviewStatus(name?'Không có file G-code cho sheet này.':'Chưa chọn sheet.',true);return;
  }
  n2gGcodePreview.states=n2gGcodePreviewParseStates(n2gGcodePreview.current.lines);
  n2gGcodePreviewStatus('');
  n2gGcodePreviewRenderWindow(0);
  n2gGcodePreviewUpdateState(0);
}

function n2gGcodePreviewRenderWindow(activeLine){
  var cur=n2gGcodePreview.current,box=document.getElementById('tp-gcode-lines');
  if(!cur||!box)return;
  var total=cur.lines.length,center=Math.max(0,activeLine|0);
  var start=Math.max(0,center-140),end=Math.min(total,start+320);
  if(end-start<320)start=Math.max(0,end-320);
  var frag=document.createDocumentFragment();
  for(var i=start;i<end;i++){
    var row=document.createElement('div');row.className='tp-gcode-line'+(i===activeLine?' active':'');row.dataset.line=i;row.dataset.number=String(i+1);
    row.onclick=(function(line){return function(){
      n2gGcodePreviewSeekLine(line);
      var list=document.getElementById('tp-gcode-lines');if(list)list.focus();
    };})(i);
    var code=document.createElement('span');code.className='lc';code.textContent=cur.lines[i]||' ';
    row.appendChild(code);frag.appendChild(row);
  }
  box.innerHTML='';box.appendChild(frag);
  if(activeLine>=0){var active=box.querySelector('.active');if(active)active.scrollIntoView({block:'center'});}
}

function n2gGcodePreviewParseStates(lines){
  var states=[],modal={x:null,y:null,z:null,feed:null,tool:null};
  function word(clean,letter){
    var re=new RegExp('(?:^|\\s)'+letter+'\\s*(-?\\d+(?:\\.\\d+)?)','i'),m=clean.match(re);
    return m?+m[1]:null;
  }
  (lines||[]).forEach(function(raw){
    var clean=String(raw||'').replace(/\([^)]*\)/g,'').replace(/;.*$/,'');
    var x=word(clean,'X'),y=word(clean,'Y'),z=word(clean,'Z'),f=word(clean,'F');
    if(x!=null)modal.x=x;if(y!=null)modal.y=y;if(z!=null)modal.z=z;if(f!=null)modal.feed=f;
    var tm=clean.match(/(?:^|\s)T\s*(\d+)/i);if(tm)modal.tool='T'+tm[1];
    var motionMatch=clean.match(/(?:^|\s)(G0?[0123])(?=\s|$)/i);
    var motion=!!motionMatch;
    states.push({x:modal.x,y:modal.y,z:modal.z,feed:modal.feed,tool:modal.tool,
      i:word(clean,'I'),j:word(clean,'J'),k:word(clean,'K'),
      motion:motionMatch?motionMatch[1].toUpperCase():null,motionXY:motion&&(x!=null||y!=null)});
  });
  return states;
}

function n2gGcodePreviewUpdateState(line){
  var s=n2gGcodePreview.states[line]||{};
  var pos=document.getElementById('tp-gcode-position');
  if(pos){
    var total=n2gGcodePreview.current&&n2gGcodePreview.current.lines?n2gGcodePreview.current.lines.length:0;
    pos.textContent=total?('Dòng '+(Math.max(0,line|0)+1)+' / '+total):'Dòng — / —';
  }
  function put(id,value,digits){
    var el=document.getElementById(id);if(!el)return;
    el.textContent=(value==null||value==='')?'—':(typeof value==='number'?value.toFixed(digits):String(value));
  }
  put('tp-gcode-x',s.x,4);put('tp-gcode-y',s.y,4);put('tp-gcode-z',s.z,4);
  put('tp-gcode-i',s.i,4);put('tp-gcode-j',s.j,4);put('tp-gcode-k',s.k,4);
  put('tp-gcode-tool',s.tool,0);put('tp-gcode-feed',s.feed,4);
}

function n2gGcodePreviewMotions(lines){
  var out=[],x=null,y=null;
  (lines||[]).forEach(function(raw,line){
    var clean=raw.replace(/\([^)]*\)/g,'').replace(/;.*$/,'').toUpperCase();
    var gm=clean.match(/(?:^|\s)(G0?0|G0?1|G0?2|G0?3)(?=\s|$)/);if(!gm)return;
    var xm=clean.match(/(?:^|\s)X\s*(-?\d+(?:\.\d+)?)/),ym=clean.match(/(?:^|\s)Y\s*(-?\d+(?:\.\d+)?)/);
    if(!xm&&!ym)return;
    if(xm)x=+xm[1];if(ym)y=+ym[1];
    if(x!=null&&y!=null)out.push({line:line,x:x,y:y,code:gm[1]});
  });
  return out;
}

function n2gGcodePreviewBindSegments(segs){
  var cur=n2gGcodePreview.current;if(!cur||!segs)return;
  var motions=n2gGcodePreviewMotions(cur.lines),map=new Array(segs.length),si=0,tol2=0.08*0.08;
  for(var mi=0;mi<motions.length&&si<segs.length;mi++){
    var m=motions[mi],found=-1,limit=Math.min(segs.length,si+2500);
    for(var k=si;k<limit;k++){
      var dx=segs[k].x2-m.x,dy=segs[k].y2-m.y;
      if(dx*dx+dy*dy<=tol2){found=k;break;}
    }
    if(found>=0){for(var q=si;q<=found;q++)map[q]=m.line;si=found+1;}
  }
  n2gGcodePreview.lineMap=map;
  n2gGcodePreviewSetSegment(0);
}

function n2gGcodePreviewSetSegment(segIndex){
  var line=n2gGcodePreview.lineMap[segIndex];if(line==null)return;
  if(line===n2gGcodePreview.activeLine)return;
  n2gGcodePreview.activeLine=line;n2gGcodePreviewRenderWindow(line);n2gGcodePreviewUpdateState(line);
}

function n2gGcodePreviewSeekLine(line){
  if(typeof simPause==='function')simPause();
  if((!simAnim.segs||!simAnim.segs.length)&&typeof simPrepare==='function')simPrepare();
  if(!simAnim.segs||!simAnim.segs.length)return;
  var best=-1,seekDist=null,state=n2gGcodePreview.states[line];
  // Direct coordinate lookup makes keyboard stepping follow every G0/G1/G2/G3
  // line even when a repeated start point or a Z-only command confused the
  // sequential line map. Prefer the occurrence nearest the current progress.
  if(state&&state.motionXY&&state.x!=null&&state.y!=null){
    var bestD=Infinity,bestProgress=Infinity,curIdx=Math.max(0,simAnim.segIdx||0);
    var isArc=state.motion==='G2'||state.motion==='G02'||state.motion==='G3'||state.motion==='G03';
    var isG1=state.motion==='G1'||state.motion==='G01';
    // A circle emitted as many G1 points rarely shares the same sampling as
    // simCircleToPts. Project the NC coordinate onto each cutting segment and
    // retain the distance travelled inside that segment.
    if(isG1){
      for(var pi=0;pi<simAnim.segs.length;pi++){
        var pg=simAnim.segs[pi];if(pg.isTravel)continue;
        var vx=pg.x2-pg.x1,vy=pg.y2-pg.y1,len2=vx*vx+vy*vy;
        if(len2<1e-12)continue;
        var t=((state.x-pg.x1)*vx+(state.y-pg.y1)*vy)/len2;t=Math.max(0,Math.min(1,t));
        var px=pg.x1+vx*t,py=pg.y1+vy*t,pdx=px-state.x,pdy=py-state.y,pd=pdx*pdx+pdy*pdy;
        var pp=Math.abs(pi-curIdx);
        if(pd<bestD-1e-8||(Math.abs(pd-bestD)<=1e-8&&pp<bestProgress)){
          bestD=pd;bestProgress=pp;best=pi;seekDist=(pg.len||Math.sqrt(len2))*t;
        }
      }
      if(best>=0){
        var matchSeg=simAnim.segs[best];
        var tol=(matchSeg.type==='circle')?Math.max(2,(matchSeg.len||0)*0.15):0.5;
        if(bestD>tol*tol){best=-1;seekDist=null;bestD=Infinity;bestProgress=Infinity;}
      }
    }
    for(var si=0;!isG1&&si<simAnim.segs.length;si++){
      var sg=simAnim.segs[si],dx=sg.x2-state.x,dy=sg.y2-state.y,d=dx*dx+dy*dy;
      // Analytic G2/G3 from Ruby corresponds to the polygonal circle used by
      // the canvas simulator. Restrict lookup to that path type so a nearby
      // profile endpoint cannot steal the match.
      if(isArc&&sg.type!=='circle')continue;
      var progress=Math.abs(si-curIdx);
      if(d<bestD-1e-8||(Math.abs(d-bestD)<=1e-8&&progress<bestProgress)){
        bestD=d;bestProgress=progress;best=si;
      }
    }
    // Linear endpoints should be effectively identical. Circle endpoints may
    // differ slightly because Ruby uses an analytic radius while canvas uses
    // sampled points, so accept the nearest circle segment without this cap.
    if(!isArc&&!isG1&&bestD>0.25)best=-1;
    if(isArc&&bestD>4){
      // Non-circle arcs (ordinary curved profile) retain the generic lookup.
      best=-1;bestD=Infinity;
      for(var ai=0;ai<simAnim.segs.length;ai++){
        var ag=simAnim.segs[ai],adx=ag.x2-state.x,ady=ag.y2-state.y,ad=adx*adx+ady*ady;
        if(ad<bestD){bestD=ad;best=ai;}
      }
    }
  }
  for(var i=0;i<n2gGcodePreview.lineMap.length;i++){
    var mapped=n2gGcodePreview.lineMap[i];
    if(mapped==null)continue;
    if(best<0&&mapped<=line)best=i;
    if(mapped>line)break;
  }
  if(best<0)best=0;
  var done=0;for(var k=0;k<best;k++)done+=simAnim.segs[k].len||0;
  var seg=simAnim.segs[best];
  var atDist=seekDist==null?(seg.len||0):Math.max(0,Math.min(seg.len||0,seekDist));
  simAnim.segIdx=best;simAnim.segDist=atDist;simAnim.doneLen=done+atDist;
  simAnim.done=false;simAnim.lastT=performance.now();
  if(typeof simRenderFrame==='function')simRenderFrame();
  if(typeof simSetProgress==='function')simSetProgress(Math.min(100,(simAnim.doneLen/simAnim.totalLen)*100));
  n2gGcodePreview.activeLine=line;n2gGcodePreviewRenderWindow(line);n2gGcodePreviewUpdateState(line);
}

function n2gGcodePreviewKeydown(event){
  if(!event||(event.key!=='ArrowUp'&&event.key!=='ArrowDown'))return;
  var cur=n2gGcodePreview.current;if(!cur||!cur.lines||!cur.lines.length)return;
  event.preventDefault();event.stopPropagation();
  var line=n2gGcodePreview.activeLine;
  if(line<0)line=0;
  else line+=event.key==='ArrowUp'?-1:1;
  line=Math.max(0,Math.min(cur.lines.length-1,line));
  n2gGcodePreviewSeekLine(line);
  var list=document.getElementById('tp-gcode-lines');if(list)list.focus();
}

function n2gGcodePreviewReset(){
  n2gGcodePreview.activeLine=-1;
  if(n2gGcodePreview.current){n2gGcodePreviewRenderWindow(0);n2gGcodePreviewUpdateState(0);}
}
